#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

#define LINE_MAX 0x800
#define DECODE_MAX 0x800

static size_t url_decode(const char *src, char *dst) {
    size_t out = 0;
    while (*src) {
        if (*src == '+') {
            dst[out++] = ' ';
            src++;
        } else if (*src == '%' && isxdigit((unsigned char)src[1]) && isxdigit((unsigned char)src[2])) {
            char hex[3] = { src[1], src[2], 0 };
            dst[out++] = (char)strtoul(hex, NULL, 16);
            src += 3;
        } else {
            dst[out++] = *src++;
        }
    }
    dst[out] = '\0';
    return out;
}

int main(void) {
    static char line[LINE_MAX];
    static char key_buf[DECODE_MAX];
    static char val_buf[DECODE_MAX];

    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    size_t len = strlen(line);
    while (len && (line[len-1] == '\n' || line[len-1] == '\r')) {
        line[--len] = '\0';
    }
    if (len == 0) return 0;

    const char *p = line;
    while (*p) {
        const char *token_end = strchr(p, '&');
        if (!token_end) token_end = p + strlen(p);
        const char *eq = memchr(p, '=', (size_t)(token_end - p));
        if (eq) {
            size_t key_len = (size_t)(eq - p);
            size_t val_len = (size_t)(token_end - (eq + 1));
            char raw_key[DECODE_MAX];
            char raw_val[DECODE_MAX];
            memcpy(raw_key, p, key_len);
            raw_key[key_len] = '\0';
            memcpy(raw_val, eq + 1, val_len);
            raw_val[val_len] = '\0';
            url_decode(raw_key, key_buf);
            url_decode(raw_val, val_buf);
        } else {
            char raw_key[DECODE_MAX];
            memcpy(raw_key, p, (size_t)(token_end - p));
            raw_key[token_end - p] = '\0';
            url_decode(raw_key, key_buf);
            val_buf[0] = '\0';
        }
        printf("%s=%s\n", key_buf, val_buf);
        p = (*token_end == '&') ? token_end + 1 : token_end;
    }
    return 0;
}
